script:
const root = root_element;
const $ = (sel) => root.querySelector(sel);
const $$ = (sel) => Array.from(root.querySelectorAll(sel));

// greeting + date
const hour = new Date().getHours();
const part = hour < 12 ? __("Good morning") : hour < 17 ? __("Good afternoon") : __("Good evening");
const first_name = ((frappe.session && frappe.session.user_fullname) || "").split(" ")[0];
$(".lx-greet").textContent = first_name ? `${part}, ${first_name}` : part;
$(".lx-date").textContent = new Date().toLocaleDateString(undefined, {
	weekday: "long", day: "numeric", month: "long", year: "numeric",
});

// quick actions
$$("[data-new]").forEach((btn) => {
	btn.addEventListener("click", () => frappe.new_doc(btn.dataset.new));
});

// stats
const month_start = frappe.datetime.month_start();
const STATS = {
	inbound: {
		doctype: "Inbound",
		filters: { docstatus: 1 },
		month: true,
	},
	open_inbound: {
		doctype: "Inbound",
		filters: { docstatus: 1, status: ["in", ["Pending", "Partially"]] },
		of: "inbound",
		of_label: __("of inbound still open"),
	},
	outbound: {
		doctype: "Outbound",
		filters: { docstatus: 1 },
		month: true,
	},
	delivery_note: {
		doctype: "Logistics Delivery Note",
		filters: { docstatus: ["!=", 2] },
		month: true,
	},
};

const reduce_motion = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

function count_up(el, target) {
	if (reduce_motion) {
		el.textContent = format_number(target);
		return;
	}
	const duration = 1400;
	const start = performance.now();
	const step = (now) => {
		const t = Math.min((now - start) / duration, 1);
		const eased = 1 - Math.pow(1 - t, 3);
		el.textContent = format_number(Math.round(target * eased));
		if (t < 1) requestAnimationFrame(step);
	};
	requestAnimationFrame(step);
}

function format_number(n) {
	return Number(n).toLocaleString();
}

function safe_count(doctype, filters) {
	return frappe.db.count(doctype, { filters }).catch(() => null);
}

const results = {};

Promise.all(
	Object.entries(STATS).map(([key, cfg]) => {
		const calls = [safe_count(cfg.doctype, cfg.filters)];
		if (cfg.month) {
			calls.push(safe_count(cfg.doctype, Object.assign({}, cfg.filters, { posting_date: [">=", month_start] })));
		}
		return Promise.all(calls).then(([total, this_month]) => {
			results[key] = { total, this_month };
		});
	})
).then(() => {
	Object.entries(STATS).forEach(([key, cfg]) => {
		const card = $(`.lx-stat[data-key="${key}"]`);
		const { total, this_month } = results[key];
		const num = card.querySelector("[data-count]");
		const meta = card.querySelector("[data-meta]");
		const bar = card.querySelector(".lx-bar span");

		if (total === null || total === undefined) {
			num.textContent = "—";
			meta.textContent = __("Not available");
			return;
		}
		count_up(num, total);

		let ratio = 0;
		if (cfg.of) {
			const base = (results[cfg.of] || {}).total || 0;
			ratio = base ? total / base : 0;
			meta.innerHTML = `<b>${Math.round(ratio * 100)}%</b> ${cfg.of_label}`;
		} else if (cfg.month) {
			const m = this_month || 0;
			ratio = total ? m / total : 0;
			meta.innerHTML = `<b>+${format_number(m)}</b> ${__("this month")}`;
		}
		// tiny delay so the bar animates after the card fades in
		setTimeout(() => {
			bar.style.width = `${Math.max(4, Math.round(ratio * 100))}%`;
		}, 250);
	});
});

// click a stat → open its list
$$(".lx-stat").forEach((card) => {
	card.addEventListener("click", (e) => {
		e.preventDefault();
		const cfg = STATS[card.dataset.key];
		frappe.set_route("List", cfg.doctype, cfg.filters);
	});
});

style:
:host { display: block; }
.lx {
  --lx-card: var(--card-bg, #ffffff);
  --lx-text: var(--heading-color, #1f272e);
  --lx-muted: var(--text-muted, #7c7c7c);
  --lx-border: var(--border-color, #ededed);
  font-family: var(--font-stack, Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif);
  color: var(--lx-text);
}

/* ---------- hero ---------- */
.lx-hero {
  position: relative;
  overflow: hidden;
  border-radius: 16px;
  padding: 26px 28px 0;
  color: #fff;
  background: linear-gradient(120deg, #0b4f9c, #1c8ce3, #2bb3ef, #1c8ce3, #0b4f9c);
  background-size: 300% 300%;
  animation: lx-gradient 14s ease infinite, lx-rise .6s ease-out both;
  box-shadow: 0 10px 30px -12px rgba(11, 79, 156, .55);
}
.lx-glow { position: absolute; border-radius: 50%; filter: blur(40px); opacity: .35; pointer-events: none; }
.lx-glow-a { width: 260px; height: 260px; background: #7fd3ff; top: -120px; right: 8%; animation: lx-float 9s ease-in-out infinite; }
.lx-glow-b { width: 200px; height: 200px; background: #ffd54a; bottom: -140px; left: 30%; opacity: .18; animation: lx-float 11s ease-in-out infinite reverse; }

.lx-hero-top { position: relative; display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 18px; }
.lx-eyebrow { display: flex; align-items: center; gap: 8px; font-size: 12px; letter-spacing: .06em; text-transform: uppercase; opacity: .85; }
.lx-live { width: 8px; height: 8px; border-radius: 50%; background: #5cf2a5; box-shadow: 0 0 0 0 rgba(92, 242, 165, .7); animation: lx-pulse 2s infinite; }
.lx-title { margin: 6px 0 4px; font-size: 26px; font-weight: 700; line-height: 1.2; color: #fff; }
.lx-sub { margin: 0; font-size: 14px; opacity: .85; }

.lx-actions { display: flex; flex-wrap: wrap; gap: 8px; }
.lx-btn {
  font: inherit; font-size: 13px; font-weight: 600; cursor: pointer;
  border: 1px solid rgba(255, 255, 255, .35); border-radius: 10px; padding: 8px 14px;
  color: #fff; background: rgba(255, 255, 255, .14); backdrop-filter: blur(6px);
  transition: transform .18s ease, background .18s ease, box-shadow .18s ease;
}
.lx-btn:hover { transform: translateY(-2px); background: rgba(255, 255, 255, .26); box-shadow: 0 6px 16px -6px rgba(0, 0, 0, .35); }
.lx-btn:active { transform: translateY(0); }
.lx-btn:focus-visible { outline: 2px solid #fff; outline-offset: 2px; }
.lx-plus { display: inline-block; transition: transform .25s ease; }
.lx-btn:hover .lx-plus { transform: rotate(90deg); }

/* road + truck */
.lx-road { position: relative; height: 64px; margin: 18px -28px 0; }
.lx-lane {
  position: absolute; left: 0; right: 0; bottom: 6px; height: 3px;
  background: repeating-linear-gradient(90deg, rgba(255, 255, 255, .55) 0 26px, transparent 26px 48px);
  background-size: 48px 3px;
  animation: lx-lane .8s linear infinite;
}
.lx-truck { position: absolute; bottom: 7px; left: -110px; animation: lx-drive 12s linear infinite; }
.lx-wheel { transform-box: fill-box; transform-origin: center; animation: lx-spin .6s linear infinite; }
.lx-box { position: absolute; bottom: 10px; width: 18px; height: 18px; border-radius: 3px; background: #ffd54a; opacity: .9;
  box-shadow: inset 0 -5px 0 rgba(0, 0, 0, .12); animation: lx-bob 3s ease-in-out infinite; }
.lx-box::after { content: ""; position: absolute; left: 7px; top: 0; width: 4px; height: 100%; background: rgba(11, 79, 156, .35); }
.lx-box-1 { right: 16%; }
.lx-box-2 { right: calc(16% + 22px); animation-delay: .4s; }
.lx-box-3 { right: calc(16% + 11px); bottom: 30px; animation-delay: .8s; }

/* ---------- stats ---------- */
.lx-stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 14px; margin-top: 16px; }
.lx-stat {
  position: relative; overflow: hidden; display: block; cursor: pointer; text-decoration: none !important;
  color: var(--lx-text) !important; background: var(--lx-card); border: 1px solid var(--lx-border);
  border-radius: 14px; padding: 16px 18px 18px;
  animation: lx-rise .55s cubic-bezier(.2, .7, .2, 1) both; animation-delay: calc(.12s + var(--d) * .09s);
  transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
}
.lx-stat::before { content: ""; position: absolute; inset: 0 auto 0 0; width: 4px; background: var(--accent); }
.lx-stat:hover { transform: translateY(-4px); border-color: var(--accent); box-shadow: 0 12px 24px -14px var(--accent); }
.lx-stat-head { display: flex; align-items: center; gap: 8px; font-size: 13px; font-weight: 600; color: var(--lx-muted); }
.lx-ico {
  display: inline-grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; font-size: 15px;
  color: var(--accent); background: color-mix(in srgb, var(--accent) 14%, transparent);
  transition: transform .3s ease;
}
.lx-stat:hover .lx-ico { transform: scale(1.12) rotate(-6deg); }
.lx-num { margin-top: 10px; font-size: 30px; font-weight: 700; line-height: 1; font-variant-numeric: tabular-nums; letter-spacing: -.01em; }
.lx-meta { margin-top: 8px; font-size: 12px; color: var(--lx-muted); min-height: 16px; }
.lx-meta b { color: var(--accent); font-weight: 600; }
.lx-bar { margin-top: 12px; height: 4px; border-radius: 4px; background: var(--lx-border); overflow: hidden; }
.lx-bar span { display: block; height: 100%; width: 0; border-radius: 4px; background: var(--accent); transition: width 1.2s cubic-bezier(.2, .7, .2, 1); }

/* ---------- keyframes ---------- */
@keyframes lx-gradient { 0% { background-position: 0% 50%; } 50% { background-position: 100% 50%; } 100% { background-position: 0% 50%; } }
@keyframes lx-rise { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
@keyframes lx-float { 0%, 100% { transform: translate(0, 0); } 50% { transform: translate(-30px, 20px); } }
@keyframes lx-pulse { 0% { box-shadow: 0 0 0 0 rgba(92, 242, 165, .7); } 70% { box-shadow: 0 0 0 9px rgba(92, 242, 165, 0); } 100% { box-shadow: 0 0 0 0 rgba(92, 242, 165, 0); } }
@keyframes lx-lane { to { background-position: -48px 0; } }
@keyframes lx-drive { 0% { left: -110px; } 100% { left: 100%; } }
@keyframes lx-spin { to { transform: rotate(360deg); } }
@keyframes lx-bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-3px); } }

/* ---------- responsive ---------- */
@media (max-width: 991px) { .lx-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 575px) {
  .lx-hero { padding: 20px 18px 0; }
  .lx-road { margin: 14px -18px 0; }
  .lx-title { font-size: 21px; }
  .lx-num { font-size: 26px; }
  .lx-stats { gap: 10px; }
}
@media (prefers-reduced-motion: reduce) {
  .lx *, .lx *::before, .lx-hero, .lx-stat { animation: none !important; transition: none !important; }
  .lx-truck { left: 40%; }
}
